package com.simibubi.create.test;

import com.simibubi.create.*;
import com.simibubi.create.content.contraptions.*;
import com.simibubi.create.content.contraptions.bearing.BearingContraption;
import com.simibubi.create.content.contraptions.glue.SuperGlueEntity;
import com.simibubi.create.foundation.item.LoadedItemStorage;
import com.simibubi.create.foundation.fluid.FluidStack;
import java.util.*;
import net.fabricmc.fabric.api.gametest.v1.GameTest;
import net.fabricmc.fabric.api.transfer.v1.item.*;
import net.fabricmc.fabric.api.transfer.v1.fluid.*;
import net.fabricmc.fabric.api.transfer.v1.transaction.Transaction;
import net.minecraft.core.*;
import net.minecraft.core.component.DataComponents;
import net.minecraft.gametest.framework.GameTestHelper;
import net.minecraft.nbt.*;
import net.minecraft.network.chat.Component;
import net.minecraft.world.entity.item.ItemEntity;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.*;
import net.minecraft.world.level.block.entity.*;
import net.minecraft.world.level.block.state.properties.BlockStateProperties;
import net.minecraft.world.level.material.Fluids;
import net.minecraft.world.phys.*;

public class ContraptionAssemblyGameTests {
    private static final BlockPos P=new BlockPos(3,5,3),T=P.south(3);
    private static BearingContraption assemble(GameTestHelper h)throws AssemblyException{var result=new BearingContraption(false,Direction.EAST);h.assertTrue(result.assemble(h.getLevel(),h.absolutePos(P.west())),"Structure assembled");return result;}
    private static void glue(GameTestHelper h,BlockPos a,BlockPos b){h.getLevel().addFreshEntity(new SuperGlueEntity(h.getLevel(),SuperGlueEntity.span(h.absolutePos(a),h.absolutePos(b))));}
    private static StructureTransform transform(GameTestHelper h,int x,int y,int z){return new StructureTransform(h.absolutePos(T),x,y,z);}
    private static void remove(GameTestHelper h,Contraption structure)throws AssemblyException{h.assertTrue(structure.tryRemoveBlocksFromWorld(h.getLevel(),BlockPos.ZERO),"World ownership transferred");}
    private static void restore(GameTestHelper h,Contraption structure,StructureTransform transform)throws AssemblyException{h.assertTrue(structure.tryAddBlocksToWorld(h.getLevel(),transform),"Structure returned to world");}
    private static ItemStack named(){var item=new ItemStack(Items.DIAMOND,7);item.set(DataComponents.CUSTOM_NAME,Component.literal("Moved components"));return item;}
    private static void noDrops(GameTestHelper h){h.assertTrue(h.getLevel().getEntitiesOfClass(ItemEntity.class,new AABB(h.absolutePos(P)).inflate(9)).isEmpty(),"Assembly does not produce inventory or block drops");}
    @GameTest public void ordinaryBlocksOnlyJoinThroughAnActualAttachment(GameTestHelper h)throws Exception{h.setBlock(P,Blocks.STONE);h.setBlock(P.east(),Blocks.STONE);var structure=assemble(h);h.assertValueEqual(structure.getBlocks().size(),1,"Touching ordinary stone is not sticky");h.assertBlockPresent(Blocks.STONE,P);h.assertValueEqual(structure.phase(),Contraption.Phase.CAPTURED,"Capture has not removed world blocks");h.succeed();}
    @GameTest public void glueConnectsStructureButDoesNotTakeWorldOwnershipDuringSearch(GameTestHelper h)throws Exception{h.setBlock(P,Blocks.STONE);h.setBlock(P.east(),Blocks.OAK_LOG);glue(h,P,P.east());var structure=assemble(h);h.assertValueEqual(structure.getBlocks().size(),2,"Glue joins two blocks");h.assertBlockPresent(Blocks.STONE,P);h.assertTrue(SuperGlueEntity.isGlued(h.getLevel(),h.absolutePos(P),Direction.EAST,null),"Search retains original glue");remove(h,structure);h.assertBlockPresent(Blocks.AIR,P);h.assertBlockPresent(Blocks.AIR,P.east());h.assertFalse(SuperGlueEntity.isGlued(h.getLevel(),h.absolutePos(P),Direction.EAST,null),"Taken glue is no longer in world");noDrops(h);h.succeed();}
    @GameTest public void slimeAndHoneyKeepTheirVanillaIncompatibility(GameTestHelper h)throws Exception{h.setBlock(P,Blocks.SLIME_BLOCK);h.setBlock(P.east(),Blocks.HONEY_BLOCK);h.setBlock(P.south(),Blocks.STONE);var structure=assemble(h);h.assertTrue(structure.getBlocks().containsKey(new BlockPos(0,0,1)),"Slime collects ordinary solid neighbor");h.assertFalse(structure.getBlocks().containsKey(new BlockPos(1,0,0)),"Slime does not collect honey");h.succeed();}
    @GameTest public void wallAttachmentIsRemovedBeforeItsSupportAndRestoredAfterIt(GameTestHelper h)throws Exception{h.setBlock(P,Blocks.STONE);h.setBlock(P.north(),Blocks.LADDER.defaultBlockState().setValue(LadderBlock.FACING,Direction.NORTH));var structure=assemble(h);h.assertValueEqual(structure.getBlocks().size(),2,"Ladder support attachment");remove(h,structure);noDrops(h);var rotation=transform(h,0,90,0);restore(h,structure,rotation);var ladder=rotation.apply(new BlockPos(0,0,-1));h.assertTrue(h.getLevel().getBlockState(ladder).is(Blocks.LADDER),"Wall ladder survives rotated placement order");h.assertValueEqual(h.getLevel().getBlockState(ladder).getValue(LadderBlock.FACING),Direction.WEST,"Ladder facing rotated");noDrops(h);h.succeed();}
    @GameTest public void changedWorldBlockRejectsWholeRemovalWithoutPartialChanges(GameTestHelper h)throws Exception{h.setBlock(P,Blocks.STONE);h.setBlock(P.east(),Blocks.OAK_LOG);glue(h,P,P.east());var structure=assemble(h);h.setBlock(P.east(),Blocks.GOLD_BLOCK);boolean refused=false;try{structure.tryRemoveBlocksFromWorld(h.getLevel(),BlockPos.ZERO);}catch(AssemblyException expected){refused=true;}h.assertTrue(refused,"Changed source rejected");h.assertBlockPresent(Blocks.STONE,P);h.assertBlockPresent(Blocks.GOLD_BLOCK,P.east());h.assertValueEqual(structure.phase(),Contraption.Phase.CAPTURED,"Still only a capture");h.succeed();}
    @GameTest public void chestContentsAndComponentsSurviveRemovalSaveLoadAndRotation(GameTestHelper h)throws Exception{h.setBlock(P,Blocks.CHEST);var chest=h.getBlockEntity(P,ChestBlockEntity.class);chest.setItem(8,named());var structure=assemble(h);remove(h,structure);noDrops(h);var saved=structure.writeNBT(h.getLevel().registryAccess(),false);var restored=Contraption.fromNBT(h.getLevel(),saved,false);h.assertTrue(restored instanceof BearingContraption,"Public type factory");restore(h,restored,transform(h,0,90,0));var result=h.getBlockEntity(T,ChestBlockEntity.class).getItem(8);h.assertTrue(ItemStack.isSameItemSameComponents(result,named())&&result.getCount()==7,"Native chest slot/components retained");h.assertValueEqual(h.getBlockState(T).getValue(ChestBlock.FACING),Direction.WEST,"Chest yaw");noDrops(h);h.succeed();}
    @GameTest public void inventoryChangesAfterSearchAreCapturedBeforeRemoval(GameTestHelper h)throws Exception{h.setBlock(P,Blocks.BARREL);var structure=assemble(h);h.getBlockEntity(P,BarrelBlockEntity.class).setItem(4,named());remove(h,structure);restore(h,structure,transform(h,0,0,0));h.assertValueEqual(h.getBlockEntity(T,BarrelBlockEntity.class).getItem(4).getCount(),7,"Last source contents are not lost");noDrops(h);h.succeed();}
    @GameTest public void oldStorageAndHeldViewsCannotExtractOrInsertAfterWorldTransfer(GameTestHelper h)throws Exception{h.setBlock(P,AllBlocks.MILLSTONE);var storage=LoadedItemStorage.find(h.getLevel(),h.absolutePos(P),null);try(var tx=Transaction.openOuter()){storage.insert(ItemVariant.of(Items.WHEAT),5,tx);tx.commit();}var structure=assemble(h);var views=new ArrayList<net.fabricmc.fabric.api.transfer.v1.storage.StorageView<ItemVariant>>();storage.forEach(views::add);remove(h,structure);try(var tx=Transaction.openOuter()){h.assertValueEqual(storage.insert(ItemVariant.of(Items.WHEAT),4,tx),0L,"Old world insertion rejected");h.assertValueEqual(storage.extract(ItemVariant.of(Items.WHEAT),4,tx),0L,"Old world extraction rejected");for(var view:views){h.assertValueEqual(view.getAmount(),0L,"Held views are invalidated");h.assertValueEqual(view.extract(ItemVariant.of(Items.WHEAT),4,tx),0L,"Held view cannot extract");}tx.commit();}h.succeed();}
    @GameTest public void waterloggingLeavesWaterAtSourceAndUsesTargetWaterWhenRestoring(GameTestHelper h)throws Exception{h.setBlock(P,AllBlocks.SHAFT.defaultBlockState().setValue(BlockStateProperties.WATERLOGGED,true));var structure=assemble(h);remove(h,structure);h.assertBlockPresent(Blocks.WATER,P);restore(h,structure,transform(h,0,0,0));h.assertFalse(h.getBlockState(T).getValue(BlockStateProperties.WATERLOGGED),"Dry target does not carry source water");h.succeed();}
    @GameTest public void repeatRestorationCannotDuplicateBlocksOrOwnedInventory(GameTestHelper h)throws Exception{h.setBlock(P,Blocks.BARREL);h.getBlockEntity(P,BarrelBlockEntity.class).setItem(0,named());var structure=assemble(h);remove(h,structure);restore(h,structure,transform(h,0,0,0));h.assertFalse(structure.tryAddBlocksToWorld(h.getLevel(),new StructureTransform(h.absolutePos(T.east()),0,0,0)),"Already disassembled owner cannot place again");h.assertBlockPresent(Blocks.AIR,T.east());h.assertValueEqual(h.getBlockEntity(T,BarrelBlockEntity.class).getItem(0).getCount(),7,"Exactly one payload");h.succeed();}
    @GameTest public void unloadedRestorationLeavesCapturedOwnershipAndDoesNotLoadTarget(GameTestHelper h)throws Exception{h.setBlock(P,Blocks.STONE);var structure=assemble(h);remove(h,structure);var far=new BlockPos(100000,20,100000);boolean refused=false;try{structure.tryAddBlocksToWorld(h.getLevel(),new StructureTransform(far,0,0,0));}catch(AssemblyException expected){refused=true;}h.assertTrue(refused,"Unloaded destination rejected");h.assertValueEqual(structure.phase(),Contraption.Phase.REMOVED,"Structure keeps removed block");h.assertTrue(h.getLevel().getChunkSource().getChunkNow(far.getX()>>4,far.getZ()>>4)==null,"No loading lookup");restore(h,structure,transform(h,0,0,0));h.assertBlockPresent(Blocks.STONE,T);h.succeed();}
    @GameTest public void spawnPayloadUsesUpdateTagsInsteadOfChestInventory(GameTestHelper h)throws Exception{h.setBlock(P,Blocks.CHEST);h.getBlockEntity(P,ChestBlockEntity.class).setItem(0,named());var structure=assemble(h);remove(h,structure);var full=structure.writeNBT(h.getLevel().registryAccess(),false);var spawn=structure.writeNBT(h.getLevel().registryAccess(),true);h.assertTrue(full.toString().contains("Moved components"),"Saved data contains owned inventory");h.assertFalse(spawn.toString().contains("Moved components"),"Private chest inventory not exposed as render state");h.assertValueEqual(Contraption.fromNBT(h.getLevel(),spawn,true).getBlocks().size(),1,"Client reads native spawn structure");h.succeed();}
    @FunctionalInterface private interface Checked {void run()throws Exception;}
    private static void checked(Checked body){try{body.run();}catch(RuntimeException failure){throw failure;}catch(Exception failure){throw new RuntimeException(failure);}}
    private static com.simibubi.create.content.fluids.tank.FluidTankBlockEntity tank(GameTestHelper h,BlockPos pos){return h.getBlockEntity(pos,com.simibubi.create.content.fluids.tank.FluidTankBlockEntity.class);}
    private static void tanks(GameTestHelper h){for(var pos:List.of(P,P.east(),P.south(),P.east().south()))h.setBlock(pos,AllBlocks.FLUID_TANK);}
    private static long totalFluid(GameTestHelper h,List<BlockPos> positions){long amount=0;for(var pos:positions){var part=tank(h,pos);if(part.isController())amount+=part.getTankInventory().getFluidAmount();}return amount;}
    @GameTest(maxTicks=35) public void tankControllerMovesToRotatedMinimumCornerWithoutFluidLoss(GameTestHelper h){tanks(h);h.runAfterDelay(5,()->checked(()->{
        var master=tank(h,P).getControllerBE();h.assertValueEqual(master.getWidth(),2,"Original 2x2 multiblock");master.getTankInventory().fill(new FluidStack(FluidVariant.of(Fluids.WATER),20*FluidConstants.BUCKET));
        var structure=assemble(h);h.assertValueEqual(structure.getBlocks().size(),4,"Whole multiblock captured through attachment rules");remove(h,structure);noDrops(h);
        var reloaded=Contraption.fromNBT(h.getLevel(),structure.writeNBT(h.getLevel().registryAccess(),false),false);var rotation=transform(h,0,90,0);restore(h,reloaded,rotation);
        var cells=List.of(T,T.north(),T.east(),T.east().north());for(var pos:cells)if(!(h.getLevel().getBlockEntity(h.absolutePos(pos)) instanceof com.simibubi.create.content.fluids.tank.FluidTankBlockEntity))Create.LOGGER.error("Tank restore missing: origin={}, target={}, state={}, local blocks={}, actual targets={}",structure.anchor,h.absolutePos(pos),h.getLevel().getBlockState(h.absolutePos(pos)),structure.getBlocks().keySet(),structure.getBlocks().keySet().stream().map(rotation::apply).toList());h.assertValueEqual(totalFluid(h,cells),20*FluidConstants.BUCKET,"One real owner still has all twenty buckets");h.assertTrue(tank(h,T.north()).isController(),"New minimum corner owns tank data");h.succeed();
    }));}
    @GameTest(maxTicks=35) public void rollingTankResplitsAndReformsWithoutClampingFluid(GameTestHelper h){tanks(h);h.runAfterDelay(5,()->checked(()->{
        tank(h,P).getControllerBE().getTankInventory().fill(new FluidStack(FluidVariant.of(Fluids.WATER),20*FluidConstants.BUCKET));var structure=assemble(h);remove(h,structure);restore(h,structure,transform(h,0,0,90));
        h.assertValueEqual(totalFluid(h,List.of(T,T.above(),T.south(),T.south().above())),20*FluidConstants.BUCKET,"Initial single-part payloads preserve total fluid");
    }));h.runAfterDelay(10,()->{h.assertValueEqual(totalFluid(h,List.of(T,T.above(),T.south(),T.south().above())),20*FluidConstants.BUCKET,"New vertical columns preserve total after connectivity ticks");noDrops(h);h.succeed();});}
    @GameTest(maxTicks=35) public void rotatedVaultKeepsEachComponentsOwnedSlotsAndExposesCombinedStorage(GameTestHelper h){var state=AllBlocks.ITEM_VAULT.defaultBlockState().setValue(com.simibubi.create.content.logistics.vault.ItemVaultBlock.HORIZONTAL_AXIS,Direction.Axis.X);h.setBlock(P,state);h.setBlock(P.east(),state);h.runAfterDelay(5,()->checked(()->{
        var first=h.getBlockEntity(P,com.simibubi.create.content.logistics.vault.ItemVaultBlockEntity.class);var second=h.getBlockEntity(P.east(),com.simibubi.create.content.logistics.vault.ItemVaultBlockEntity.class);
        try(var tx=Transaction.openOuter()){first.getInventoryOfBlock().insert(ItemVariant.of(Items.APPLE),5,tx);second.getInventoryOfBlock().insert(ItemVariant.of(Items.DIAMOND),7,tx);tx.commit();}
        var structure=assemble(h);h.assertValueEqual(structure.getBlocks().size(),2,"Connected vault collected");remove(h,structure);noDrops(h);var restored=Contraption.fromNBT(h.getLevel(),structure.writeNBT(h.getLevel().registryAccess(),false),false);restore(h,restored,transform(h,0,90,0));
        var a=h.getBlockEntity(T,com.simibubi.create.content.logistics.vault.ItemVaultBlockEntity.class);var b=h.getBlockEntity(T.north(),com.simibubi.create.content.logistics.vault.ItemVaultBlockEntity.class);
        h.assertValueEqual(a.inventory.inputs.getFirst().stack().getCount(),5,"First component retains apples at its own transformed position");h.assertTrue(a.inventory.inputs.getFirst().stack().is(Items.APPLE),"Local ownership not swapped with controller");h.assertValueEqual(b.inventory.inputs.getFirst().stack().getCount(),7,"Second component retains diamonds");long total=0;for(var view:a.storage())total+=view.getAmount();h.assertValueEqual(total,12L,"Combined moved storage is live immediately");h.succeed();
    }));}
    @GameTest public void paletteReaderAcceptsOriginalNamesPropertiesAndAnchorCompound(GameTestHelper h)throws Exception{
        h.setBlock(P,Blocks.OAK_LOG.defaultBlockState().setValue(BlockStateProperties.AXIS,Direction.Axis.X));var structure=assemble(h);remove(h,structure);var saved=structure.writeNBT(h.getLevel().registryAccess(),false);
        for(var value:saved.getCompoundOrEmpty("Blocks").getListOrEmpty("Palette"))if(value instanceof CompoundTag state){state.putString("Name",state.getStringOr("id",""));state.remove("id");if(state.contains("properties")){state.put("Properties",state.getCompoundOrEmpty("properties"));state.remove("properties");}}
        var anchor=new CompoundTag();anchor.putInt("X",h.absolutePos(P).getX());anchor.putInt("Y",h.absolutePos(P).getY());anchor.putInt("Z",h.absolutePos(P).getZ());saved.put("Anchor",anchor);saved.remove("AssemblyPhase");
        var restored=Contraption.fromNBT(h.getLevel(),saved,false);h.assertValueEqual(restored.anchor,h.absolutePos(P),"Original compound BlockPos decoded");h.assertValueEqual(restored.getBlocks().get(BlockPos.ZERO).state().getValue(BlockStateProperties.AXIS),Direction.Axis.X,"Original state Properties decoded");restore(h,restored,transform(h,0,0,0));h.succeed();
    }
    @GameTest public void invalidPaletteIndexIsRejectedInsteadOfSubstitutingAnotherBlock(GameTestHelper h)throws Exception{h.setBlock(P,Blocks.STONE);var structure=assemble(h);remove(h,structure);var saved=structure.writeNBT(h.getLevel().registryAccess(),false);((CompoundTag)saved.getCompoundOrEmpty("Blocks").getListOrEmpty("BlockList").getFirst()).putInt("State",99);boolean rejected=false;try{Contraption.fromNBT(h.getLevel(),saved,false);}catch(IllegalArgumentException expected){rejected=true;}h.assertTrue(rejected,"Malformed palette rejected");h.assertValueEqual(structure.phase(),Contraption.Phase.REMOVED,"Original owner still holds block");h.succeed();}
    @GameTest public void sourceAssemblyLimitRejectsCaptureWithoutRemovingWorldBlocks(GameTestHelper h)throws Exception{h.setBlock(P,Blocks.STONE);h.setBlock(P.east(),Blocks.STONE);glue(h,P,P.east());int old=ContraptionSettings.maxBlocksMoved;try{ContraptionSettings.maxBlocksMoved=1;boolean rejected=false;try{assemble(h);}catch(AssemblyException expected){rejected=true;}h.assertTrue(rejected,"Limit stops capture");h.assertBlockPresent(Blocks.STONE,P);h.assertBlockPresent(Blocks.STONE,P.east());}finally{ContraptionSettings.maxBlocksMoved=old;}h.succeed();}
    @GameTest public void windmillUsesSourceSailTagAndMinimumWithoutTakingBlocksOnFailure(GameTestHelper h)throws Exception{h.setBlock(P,Blocks.WOOL.pick(DyeColor.WHITE));var structure=new BearingContraption(true,Direction.EAST);boolean rejected=false;try{structure.assemble(h.getLevel(),h.absolutePos(P.west()));}catch(AssemblyException expected){rejected=true;}h.assertTrue(rejected,"One sail below source minimum");h.assertValueEqual(structure.getSailBlocks(),1,"Native wool sail tag recognized");h.assertBlockPresent(Blocks.WOOL.pick(DyeColor.WHITE),P);h.succeed();}
    @GameTest public void assemblyErrorJsonAndHighlightedPositionRoundTripThroughNativeComponentCodec(GameTestHelper h){var error=AssemblyException.unmovableBlock(h.absolutePos(P),Blocks.BEDROCK.defaultBlockState());var saved=new CompoundTag();AssemblyException.write(saved,h.getLevel().registryAccess(),error);var result=AssemblyException.read(saved,h.getLevel().registryAccess());h.assertTrue(result!=null&&result.hasPosition(),"Position retained");h.assertValueEqual(result.getPosition(),h.absolutePos(P),"Exact highlighted block");h.assertValueEqual(result.component.getString(),error.component.getString(),"Original message retained");h.succeed();}
    @GameTest public void openTransferTransactionCannotTakeWorldOwnership(GameTestHelper h)throws Exception{h.setBlock(P,Blocks.BARREL);var structure=assemble(h);try(var tx=Transaction.openOuter()){boolean refused=false;try{structure.tryRemoveBlocksFromWorld(h.getLevel(),BlockPos.ZERO);}catch(IllegalStateException expected){refused=true;}h.assertTrue(refused,"World removal cannot commit uncommitted inventory state");h.assertBlockPresent(Blocks.BARREL,P);}remove(h,structure);h.succeed();}
    @GameTest public void openTransferTransactionCannotRestoreWorldOwnership(GameTestHelper h)throws Exception{h.setBlock(P,Blocks.BARREL);h.getBlockEntity(P,BarrelBlockEntity.class).setItem(0,named());var structure=assemble(h);remove(h,structure);try(var tx=Transaction.openOuter()){boolean refused=false;try{structure.tryAddBlocksToWorld(h.getLevel(),transform(h,0,0,0));}catch(IllegalStateException expected){refused=true;}h.assertTrue(refused,"World restoration is not rolled back independently from transfer state");h.assertBlockPresent(Blocks.AIR,T);}restore(h,structure,transform(h,0,0,0));h.assertValueEqual(h.getBlockEntity(T,BarrelBlockEntity.class).getItem(0).getCount(),7,"Owner payload remains intact");h.succeed();}
}
